const fs=require('fs'), vm=require('vm'),assert=require('assert');
const html=fs.readFileSync('chip8_openai-gpt-6-sol_01.html','utf8');
const code=html.match(/<script>([\s\S]*?)<\/script>/)[1].split('window.Chip8 = Chip8;')[0];
const sandbox={Math,Uint8Array};vm.createContext(sandbox);vm.runInContext(code+'\nthis.Chip8 = Chip8; this.DEMO_ROM = DEMO_ROM; this.mnemonic = mnemonic;',sandbox);
const {Chip8,DEMO_ROM,mnemonic}=sandbox;
const c=new Chip8(DEMO_ROM);assert.equal(c.memory.length,4096);assert.equal(c.PC,0x200);assert.equal(c.memory[0x50],0xf0);assert.equal(c.memory[0x200],0x60);assert.equal(c.V.length,16);
for(let i=0;i<1000;i++) c.step(); assert(c.pixels.some(Boolean));
const d=new Chip8(DEMO_ROM);for(let i=0;i<5;i++)d.step();assert.equal(d.PC,0x20a);assert.equal(d.pixels.reduce((s,v)=>s+v,0),14);
function op(o,setup){const m=new Chip8(Uint8Array.of(o>>8,o&255));if(setup)setup(m);m.step();return m}
assert.equal(op(0x8014,m=>{m.V[0]=255;m.V[1]=1}).V[15],1);
assert.equal(op(0x8015,m=>{m.V[0]=0;m.V[1]=1}).V[15],0);
assert.equal(op(0x8017,m=>{m.V[0]=0;m.V[1]=1}).V[15],1);
assert.equal(op(0x8016,m=>m.V[1]=3).V[15],1);
assert.equal(op(0x801e,m=>m.V[1]=128).V[15],1);
assert.equal(op(0xf033,m=>{m.I=0x300;m.V[0]=247}).memory[0x301],4);
assert.equal(op(0x5010,m=>{m.V[0]=3;m.V[1]=3}).PC,0x204);
assert.equal(op(0x9010,m=>{m.V[0]=3;m.V[1]=4}).PC,0x204);
for(const invalid of [0x5011,0x9011,0x8128,0xe001,0xf0ff])assert.throws(()=>op(invalid),/Invalid opcode/);
const w=new Chip8(Uint8Array.of(0xf0,0x0a));assert.equal(w.step(),false);assert.equal(w.PC,0x200);w.keys[0xa]=1;assert.equal(w.step(),true);assert.equal(w.V[0],10);
const e=new Chip8(Uint8Array.of(0x60,0x01,0xe0,0x9e,0x61,0x03));e.keys[1]=1;e.step();e.step();assert.equal(e.PC,0x206);
const s=new Chip8(Uint8Array.of(0xd0,0x15));s.I=0x50;s.step();assert.equal(s.V[15],0);s.PC=0x200;s.step();assert.equal(s.V[15],1);assert.equal(s.pixels.reduce((a,b)=>a+b,0),0);
const t=op(0xf015,m=>m.V[0]=60);t.tickTimers(1);assert.equal(t.delayTimer,59);
assert.equal(mnemonic(0xd015),'DRW V0, V1, 5');
console.log('Passed: demo draws; arithmetic flags; invalid opcodes; key wait/skip; XOR collisions; timers; disassembly.');
NODE"}

